type Result =
  | { ok: true; value: number }
  | { ok: false; error: string };

function show(r: Result) {
  if (r.ok) {
    return `Value: ${r.value}`;   // r is the ok: true member
  }
  return `Error: ${r.error}`;     // r is the ok: false member
}

function first<T>(items: T[]): T | undefined {
  return items[0];
}

const n = first([10, 20]);      // number | undefined
const s = first(["a", "b"]);    // string | undefined

function longest<T extends { length: number }>(a: T, b: T): T {
  return a.length >= b.length ? a : b;
}
longest("apple", "fig");        // ok: strings have length
longest(10, 20);                // error: number has no length

